def _bridge(cal):
    raw = cal['bridge_raw']
    return np.linalg.lstsq(np.column_stack((raw, np.ones(len(raw)))), cal['true_channel_loads'], rcond=None)[0].sum(axis=1)

def _fit(x, past, hold, dt, times, strain, initial_rate):
    from scipy.optimize import least_squares
    n_curve = strain.size
    y = np.r_[strain.ravel(), initial_rate]

    def matrix(log_tau):
        (a, b) = _design(np.exp(log_tau), x, past, hold, dt, times)
        return np.vstack((a.reshape(-1, 7), b))

    def residual(p):
        return (matrix(p[:2]) @ p[2:] - y) / scale

    def mad(r):
        return max(1.4826 * np.median(np.abs(r - np.median(r))), 1e-07)
    grid = np.array([0.14, 0.35, 0.8, 1.7, 3.5, 7.0, 15.0])
    starts = []
    for (i, t0) in enumerate(grid):
        for t1 in grid[i + 1:]:
            log_tau = np.log([t0, t1])
            a = matrix(log_tau)
            theta = np.linalg.lstsq(a, y, rcond=None)[0]
            r = a @ theta - y
            starts.append((np.mean(np.abs(r)), np.r_[log_tau, theta], r))
    starts.sort(key=lambda row: row[0])
    r = starts[0][2]
    scale = np.r_[np.full(n_curve, mad(r[:n_curve])), np.full(len(initial_rate), mad(r[n_curve:]))]
    bounds = (np.r_[np.full(2, np.log(0.050001)), np.full(7, -np.inf)], np.r_[np.full(2, np.log(24.999999)), np.full(7, np.inf)])
    best = min((least_squares(residual, p, bounds=bounds, loss='soft_l1', x_scale='jac', max_nfev=150) for (_, p, _) in starts[:4]), key=lambda obj: obj.cost)
    r = residual(best.x) * scale
    scale = 2.5 * np.r_[np.full(n_curve, mad(r[:n_curve])), np.full(len(initial_rate), mad(r[n_curve:]))]
    p = least_squares(residual, best.x, bounds=bounds, loss='cauchy', x_scale='jac', max_nfev=150).x
    order = np.argsort(p[:2])
    return (np.exp(p[:2][order]), np.r_[p[2:4][order], p[4:]])
